INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0201','Dr. Althea','To Be Youthful Eye Serum','البشرة','العناية بالعين','سيروم تو بي يوثفول من دكتور ألثيا للعناية بمحيط العين ضمن روتينك اليومي. يتيح قوام السيروم توزيع كمية صغيرة على هذه المنطقة قبل المرطب، لإطلالة أكثر انتعاشًا ونعومة.','{"nameAr":"سيروم محيط العين تو بي يوثفول من دكتور ألثيا","tagline":"لمسة عناية لمحيط العين.","benefits":["قوام سيروم سهل التوزيع","عناية مخصصة لمحيط العين","عبوة 25 مل"],"howToUse":"ربّتي كمية صغيرة على محيط العين دون ملامسة العين أو خط الرموش، بحسب تعليمات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"eye-care","size":"25 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',10000,7500,25,'/images/catalog/TS0201-dd4a914859d8.webp','https://www.sayweee.com/en/product/Dr-Althea-To-Be-Youthful-Eye-Serum-25-ml/2920954','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0202','Maybelline','Lash Sensational Sky High Very Black','المكياج','المسكارا','ماسكارا لاش سنسيشنال سكاي هاي من ميبيلين لإبراز مظهر الرموش وتحديدها. مرري الفرشاة من الجذور للأطراف، وزيدي طبقة خفيفة عندما ترغبين بإطلالة أوضح؛ النسخة المصوّرة Very Black.','{"nameAr":"ماسكارا سكاي هاي من ميبيلين","tagline":"طول وتعريف لرموشكِ.","benefits":["تعريف للرموش","طبقات حسب الإطلالة","نسخة Very Black"],"howToUse":"مرري الفرشاة من جذور الرموش إلى الأطراف بحركات خفيفة. زيدي طبقة بحسب الإطلالة وأزيلي المكياج بلطف مساءً.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"mascara","size":"","shade":"Very Black","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',10000,6990,30,'/images/catalog/TS0202-f4c69f102aa4.webp','https://daralmashaghel.com/en/KjVZWoq','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0203','Dr. Althea','PDRN Reju 5000 Cream','البشرة','المرطبات والكريمات','كريم PDRN ريجو 5000 من دكتور ألثيا بعبوة 20 غرامًا. اختيار لخطوة الترطيب بعد السيروم، مع كمية صغيرة توزّع على البشرة لتمنحها ملمسًا أكثر نعومة ومظهرًا مرتاحًا.','{"nameAr":"كريم PDRN ريجو 5000 من دكتور ألثيا","tagline":"خطوة ترطيب لروتينكِ.","benefits":["خطوة ترطيب يومية","يناسب ترتيب روتين العناية","عبوة 20 غرامًا"],"howToUse":"وزعي كمية مناسبة على بشرة نظيفة بعد السيروم، ودلكي بلطف حتى الامتصاص وفق إرشادات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"moisturizer","size":"20 g","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0203-fa6524267b43.webp','https://allaboutskindoha.com/products/dr-althea-pdrn-reju-5000-cream-20g','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0204','M. Asam','Magic Finish Make-up Mousse','المكياج','كريم الأساس','ماجيك فينيش من إم أسام كريم أساس بقوام الموس في عبوة 30 مل. وزعي كمية قليلة بالتدريج لتوحيد مظهر لون البشرة وتجهيز قاعدة مكياج ناعمة، مع ضبط التغطية حسب الكمية المستخدمة.','{"nameAr":"موس كريم الأساس ماجيك فينيش من إم أسام","tagline":"قاعدة موس بلمسة ناعمة.","benefits":["قوام موس","تغطية قابلة للتدرج","عبوة 30 مل"],"howToUse":"حضّري البشرة بالمرطب، ثم ادمجي طبقة رقيقة بفرشاة أو إسفنجة نظيفة. أضيفي طبقة صغيرة عند الحاجة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. عامل الحماية في المكياج لا يغني عن واقي شمس مستقل بكمية كافية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"foundation","size":"30 ml","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false,"imageNote":"صورة توضيحية للمنتج؛ الدرجة أو تفاصيل الإصدار تُؤكّد مع المتجر."}',15000,10990,26,'/images/catalog/TS0204-89d1fdbc4001.webp','https://www.ebay.com/itm/405294918584','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0205','Kenta','Bebe Creme de Soin No.1','الجسم','العناية بالجسم','كريم بيبي كينتا للعناية بالبشرة بحسب العبوة المصوّرة رقم 1. يضاف إلى روتين ترطيب المناطق الجافة بكمية مناسبة، مع اتباع تعليمات العبوة؛ تأكدي من ملاءمته للعمر والمنطقة المطلوبة قبل الاستخدام.','{"nameAr":"كريم بيبي كينتا للعناية بالبشرة","tagline":"عناية بسيطة بالمناطق الجافة.","benefits":["قوام كريمي للعناية","لخطوة ترطيب موضعية","الإصدار رقم 1 المصوّر"],"howToUse":"طبقي كمية مناسبة على جلد سليم ودلكي بلطف، مع اتباع تعليمات العبوة الخاصة بالمنتج.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"body-care","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',5000,3500,30,'/images/catalog/TS0205-f55f0a8b071e.webp','https://livish.com/products/kenta-bebe-creme-de-soin-no-1','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0206','SOME BY MI','Retinol Intense Advanced Triple Action Eye Cream','البشرة','العناية بالعين','كريم العين ريتينول إنتنس من سوم باي مي لخطوة العناية المسائية بمحيط العين. ابدئي بكمية صغيرة وفق إرشادات العبوة وتدرجي في الاستخدام، مع الحفاظ على ترطيب البشرة وواقي الشمس صباحًا.','{"nameAr":"كريم العين ريتينول إنتنس من سوم باي مي","tagline":"عناية مسائية لمحيط العين.","benefits":["عناية مسائية بالعين","خطوة ريتينول تدريجية","كمية صغيرة تكفي للتوزيع"],"howToUse":"استخدمي مساءً وفق ملصق العبوة. ابدئي بكمية صغيرة وبوتيرة متباعدة حول عظمة العين بعيدًا عن الجفن المتحرك وخط الرموش، ثم رطبي البشرة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. يحتوي ريتينول؛ يُتجنب أثناء الحمل والتخطيط له، واستشيري مختصًا عند الرضاعة أو استخدام علاجات بشرة. لا تبدئيه مع مقشرات أخرى في الجلسة نفسها.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"eye-care","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0206-7fb02243cc1a.webp','https://www.mikaela-beauty.com/products/some-by-mi-retinol-intense-advanced-triple-action-eye-cream','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0207','Vichy','Capital Soleil UV-Age Daily SPF50+','البشرة','واقي الشمس','كابيتال سولاي يو في إيدج ديلي من فيشي بواقي SPF50+ كما على العبوة. فلويد لخطوة الحماية الصباحية قبل الخروج، ويُستخدم بكمية كافية مع إعادة التطبيق للحفاظ على الحماية خلال اليوم.','{"nameAr":"واقي الشمس يو في إيدج ديلي من فيشي","tagline":"حماية يومية تكمل روتينكِ.","benefits":["عامل SPF50+","قوام فلويد","خطوة الحماية الصباحية"],"howToUse":"طبقي كمية كافية ومتجانسة قبل التعرض للشمس وفق تعليمات العبوة. أعيدي التطبيق كل ساعتين وبعد السباحة أو التعرق أو التجفيف.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تجنبي شمس الظهيرة والتعرض الطويل؛ الواقي لا يوفر حماية كاملة بمفرده.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"sunscreen","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',16000,11990,25,'/images/catalog/TS0207-b2b4ab90c856.webp','https://citypharmacy.ie/products/vichy-capital-soleil-uv-age-daily-spf50-40ml?srsltid=AfmBOorX6As2PDNkbXLTM99w6EbCHkI4i45OVJ1ERZql030wdZPBf8lX','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
