INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0209','Eucerin','Advanced Hydration SPF50 Sunscreen','البشرة','واقي الشمس','واقي أدفانسد هايدريشن من يوسيرين SPF50 بعبوة 150 مل. يجمع خطوة الحماية الشمسية مع عناية ترطيب للبشرة، ويمكن إدخاله في روتين الخروج اليومي مع تطبيق كمية كافية وتجديدها.','{"nameAr":"واقي أدفانسد هايدريشن من يوسيرين SPF50","tagline":"حماية وترطيب في خطوة.","benefits":["عامل SPF50","عبوة 150 مل","خطوة حماية مع ترطيب"],"howToUse":"طبقي كمية كافية ومتجانسة قبل التعرض للشمس وفق تعليمات العبوة. أعيدي التطبيق كل ساعتين وبعد السباحة أو التعرق أو التجفيف.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تجنبي شمس الظهيرة والتعرض الطويل؛ الواقي لا يوفر حماية كاملة بمفرده.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"sunscreen","size":"150 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',15000,10990,26,'/images/catalog/TS0209-40ed506479ce.webp','https://de.iherb.com/pr/eucerin-advanced-hydration-lightweight-sunscreen-lotion-spf-50-fragrance-free-5-fl-oz-150-ml/113263','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0210','Eucerin','DermatoCLEAN Hyaluron Cleansing Gel','البشرة','الغسول والتنظيف','جل التنظيف ديرماتو كلين هيالورون من يوسيرين لخطوة تنظيف الوجه اليومية. يدلك على بشرة مبللة لإزالة الشوائب اليومية ثم يشطف، ويليه سيروم أو مرطب مناسب لنوع بشرتك.','{"nameAr":"غسول ديرماتو كلين هيالورون من يوسيرين","tagline":"بداية نظيفة لروتينكِ.","benefits":["منظف بقوام جل","يُشطف بالماء","خطوة قبل الترطيب"],"howToUse":"بللي الوجه، ودلكي كمية مناسبة بلطف بعيدًا عن العينين، ثم اشطفي جيدًا بالماء واتبعيه بمرطب.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"cleanser","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',10000,7500,25,'/images/catalog/TS0210-1f62d7e2d5af.webp','https://www.eucerin.se/produkter/dermatoclean/cleansing-gel','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0211','CeraVe','SA Smoothing Cream Urea 10%','الجسم','مرطبات الجسم والتنعيم','كريم SA سموذينغ من سيرافي مع يوريا 10% بعبوة 177 مل. عناية للجسم تجمع الترطيب والتنعيم للمناطق ذات الملمس الخشن، مع التدرج في الاستخدام واتباع تعليمات العبوة دون فرك إضافي.','{"nameAr":"كريم SA لتنعيم البشرة مع يوريا 10% من سيرافي","tagline":"ترطيب وتنعيم للمناطق الخشنة.","benefits":["يوريا 10% بحسب العبوة","عناية بملمس الجسم","عبوة 177 مل"],"howToUse":"وزعي على مناطق الجسم ذات الملمس الخشن حسب تعليمات العبوة. ابدئي على مساحة صغيرة ولا تضعيه على جلد مجروح أو متهيج.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تدرجي في الاستخدام وتجنبي جمعه مع مقشرات قوية في الروتين نفسه، واستخدمي واقي الشمس نهارًا.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"body-care","size":"177 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0211-8b077117fa97.webp','https://sensemakeupjo.com/product/cerave-sa/','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0212','Vichy','Ideal Soleil Hydrating Protective Water SPF30','البشرة','واقي الشمس','ماء الحماية والترطيب إيديال سولاي من فيشي SPF30 بعبوة 200 مل. صيغة سائلة تحتاج الرجّ واتباع تعليمات العبوة لضمان توزيع متجانس، مع تجديد التطبيق بعد السباحة أو التعرق.','{"nameAr":"ماء الحماية والترطيب إيديال سولاي من فيشي SPF30","tagline":"ماء حماية لروتين الشمس.","benefits":["عامل SPF30","عبوة 200 مل","قوام سائل للحماية"],"howToUse":"رجّي العبوة جيدًا وفق الملصق ووزعي كمية كافية ومتجانسة. جددي التطبيق كل ساعتين وبعد الماء أو التعرق أو التجفيف.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تجنبي شمس الظهيرة والتعرض الطويل؛ الواقي لا يوفر حماية كاملة بمفرده.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"sunscreen","size":"200 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',16000,11990,25,'/images/catalog/TS0212-b45c3f8e5c55.webp','https://www.notrepharma.com/protection-moyenne/10315-vichy-capital-soleil-eau-de-protection-solaire-hydratante-spf-30-spray-se-200-ml-3337875585187.html','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0213','Benefit','The POREfessional PRO Balm','المكياج','البرايمر','برايمر ذا بورفيشنال من بنفت بعبوة 44 مل لتهيئة البشرة قبل كريم الأساس. توزع كمية قليلة على المناطق المطلوبة لتنعيم مظهر سطح البشرة، ثم يضاف الفاونديشن بطبقة خفيفة.','{"nameAr":"برايمر ذا بورفيشنال من بنفت","tagline":"جهّزي قاعدة مكياجكِ.","benefits":["خطوة قبل كريم الأساس","تنعيم مظهر القاعدة","حجم 44 مل"],"howToUse":"وزعي طبقة رقيقة على المناطق المطلوبة بعد المرطب، واتركيها تستقر قبل كريم الأساس.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"primer","size":"44 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',14000,9990,28,'/images/catalog/TS0213-1c4793a4ca45.webp','https://sophies-jo.com/products/benefit-the-professional-face-primer-44ml','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0214','Paula''s Choice','Skin Perfecting 2% BHA Liquid Exfoliant','البشرة','التقشير','مقشر سكن بيرفكتنغ السائل BHA بتركيز 2% من باولا تشويس، حجم 118 مل. خطوة تقشير تُترك على البشرة بحسب تعليمات المنتج لتحسين مظهر الملمس والمسام مع الاستخدام التدريجي.','{"nameAr":"مقشر BHA السائل 2% من باولا تشويس","tagline":"تقشير سائل بخطوة محسوبة.","benefits":["BHA بتركيز 2%","مقشر يُترك على البشرة","عبوة 118 مل"],"howToUse":"بعد التنظيف، وزعي طبقة رقيقة وفق تعليمات العبوة بعيدًا عن العينين. يُترك على البشرة ولا يُشطف؛ ابدئي بوتيرة متباعدة واتبعيه بمرطب.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تدرجي في الاستخدام وتجنبي جمعه مع مقشرات قوية في الروتين نفسه، واستخدمي واقي الشمس نهارًا.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"exfoliant","size":"118 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',16000,11990,25,'/images/catalog/TS0214-5d60cdfa494f.webp','https://www.gosupps.com/paulas-choice-skin-perfecting-2-bha-liquid-salicylic-acid-exfoliant-daily-facial-exfoliator-for-blackheads-enlarged-pores-wrinkles-fine-lines-fragrance-free-paraben-free-full-size-118-ml-full-size-118ml.html','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0215','Dr. Althea','345 Relief Cream 100 ml','البشرة','المرطبات والكريمات','كريم 345 ريليف من دكتور ألثيا بحجم 100 مل، وهو حجم مستقل عن عبوة 50 مل الموجودة في المتجر. يضاف كخطوة ترطيب بعد السيروم لمنح البشرة ملمسًا ناعمًا وعناية يومية مريحة.','{"nameAr":"كريم 345 ريليف من دكتور ألثيا — 100 مل","tagline":"ريليف 345 بالحجم الكبير.","benefits":["الحجم الكبير 100 مل","خطوة بعد السيروم","عناية بملمس البشرة"],"howToUse":"وزعي كمية مناسبة على بشرة نظيفة بعد السيروم، ودلكي بلطف حتى الامتصاص وفق إرشادات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"moisturizer","size":"100 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',18000,13500,25,'/images/catalog/TS0215-bb9ec7476bb9.webp','owner-supplied:IMG_0324.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0216','Vichy','Capital Soleil Hydrating Light Spray SPF50','البشرة','واقي الشمس','بخاخ كابيتال سولاي المرطب من فيشي SPF50 لتطبيق الحماية الشمسية على المناطق المسموح بها في تعليمات العبوة. وزعيه بكمية كافية وجددّيه خلال التعرض للشمس، دون رش مباشر قرب العين أو استنشاق الرذاذ.','{"nameAr":"بخاخ الحماية كابيتال سولاي من فيشي SPF50","tagline":"توزيع خفيف للحماية.","benefits":["عامل SPF50","صيغة بخاخ","لروتين الحماية خارج المنزل"],"howToUse":"اتبعي مسافة الرش والتعليمات على العبوة ووزعي المنتج بيديك لتغطية متجانسة. لا ترشي مباشرة على الوجه ولا تستنشقي الرذاذ. جددي الحماية بانتظام.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تجنبي شمس الظهيرة والتعرض الطويل؛ الواقي لا يوفر حماية كاملة بمفرده.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"sunscreen","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',16000,11990,25,'/images/catalog/TS0216-f1f93c3d421e.webp','https://www.amavita.ch/it/p/vichy-capital-soleil-spray-fluido-protezione-cellulare-spf50-spray-200-ml-7815158','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0217','Eucerin','DermatoCLEAN Hyaluron Cleansing Milk','البشرة','مزيل المكياج','حليب التنظيف ديرماتو كلين هيالورون من يوسيرين لرفع المكياج والشوائب اليومية. يوزع على الوجه بلطف ثم يزال بالطريقة المكتوبة على العبوة، ليترك البشرة جاهزة لخطوة العناية التالية.','{"nameAr":"حليب التنظيف ديرماتو كلين هيالورون من يوسيرين","tagline":"تنظيف بحليب لطيف القوام.","benefits":["قوام حليب","خطوة إزالة المكياج","يمهد لروتين الترطيب"],"howToUse":"وزعي الحليب على الوجه ودلكي بلطف لرفع المكياج. أزيليه واشطفيه بالطريقة المحددة على العبوة قبل متابعة روتينك.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"cleanser","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',10000,7500,25,'/images/catalog/TS0217-3fbfecfc4511.webp','https://aptekifenix.bg/euserin-dermatoclean-pochistvashto-mlyako-za-suha-koja-s-hialuron-200-ml.html','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0218','Beauty of Joseon','Glow Serum Propolis Niacinamide','البشرة','السيروم','سيروم غلو من بيوتي أوف جوسون بالبروبوليس والنياسيناميد، حجم 30 مل. وزعي بضع قطرات قبل المرطب للعناية بمظهر البشرة وملمسها، مع اختبار الملاءمة إذا كانت لديك حساسية من منتجات النحل.','{"nameAr":"سيروم غلو بالبروبوليس والنياسيناميد من بيوتي أوف جوسون","tagline":"لمسة غلو في روتينكِ.","benefits":["بروبوليس ونياسيناميد","سيروم قبل المرطب","عبوة 30 مل"],"howToUse":"وزعي بضع قطرات على بشرة نظيفة، ثم اتبعيها بالمرطب. التزمي بكمية ووتيرة الاستخدام على العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تجنبيه عند التحسس من البروبوليس أو منتجات النحل.","imageType":"photo","collection":"k-beauty","featuredOrder":100,"productType":"serum","size":"30 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0218-d3e48547121d.webp','https://www.strawberrynet.com/zh-Hant-TW/beauty-of-joseon-glow-serum-propolis-niacinamide-30ml/362130','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0219','Toppik','Hair Building Fibers Dark Brown','الشعر','التصفيف وتكثيف المظهر','ألياف توبيك لتكثيف مظهر الشعر باللون البني الداكن Dark Brown، حجم 27.5 غرامًا. تنثر على الشعر الجاف في المناطق المطلوبة وتدمج بلطف للحصول على تغطية تجميلية مؤقتة للفراغات.','{"nameAr":"ألياف تكثيف الشعر من توبيك — بني داكن","tagline":"مظهر كثافة بلون بني داكن.","benefits":["درجة بني داكن","تكثيف تجميلي مؤقت","تطبيق على شعر جاف"],"howToUse":"انثري مقدارًا قليلًا على شعر جاف في المناطق المطلوبة وادمجي بلطف، مع تجنب الاستنشاق والعينين.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. نتيجة تجميلية للعناية والمظهر، وليس علاجًا مثبتًا لتساقط الشعر.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"hair-styling","size":"27.5 g","shade":"Dark Brown — بني داكن","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0219-be0d0d66e1b2.webp','https://www.ubuy.ma/en/product/21NGZZFW-toppik-hair-building-fibers-dark-brown-0-97-oz?srsltid=AfmBOoquYrrhNr_T3IDIjP9mXljom0l-cDv39WYG-DNw9seHNa-BKpTT','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0220','CeraVe','Skin Renewing Retinol Serum','البشرة','السيروم','سيروم سكن رينيوينغ ريتينول من سيرافي بحجم 30 مل للعناية المسائية بمظهر البشرة. ابدئي وفق تعليمات العبوة وبوتيرة تدريجية، ثم استخدمي مرطبًا مناسبًا وواقي شمس في الروتين الصباحي.','{"nameAr":"سيروم سكن رينيوينغ ريتينول من سيرافي","tagline":"خطوة ريتينول مسائية.","benefits":["سيروم ريتينول","عناية مسائية تدريجية","عبوة 30 مل"],"howToUse":"استخدمي مساءً على بشرة نظيفة وجافة حسب ملصق العبوة. ابدئي بوتيرة متباعدة وبكمية قليلة، ثم ضعي المرطب وواقي الشمس صباحًا.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. يحتوي ريتينول؛ يُتجنب أثناء الحمل والتخطيط له، واستشيري مختصًا عند الرضاعة أو استخدام علاجات بشرة. لا تبدئيه مع مقشرات أخرى في الجلسة نفسها.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"serum","size":"30 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',15000,10990,26,'/images/catalog/TS0220-52e6a98d2957.webp','https://murukali.com/products/cerave-skin-renewing-retinol-serum','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0221','Pixi','Jasmine Oil Blend','البشرة','زيوت الوجه','مزيج زيت الياسمين من بيكسي لخطوة العناية بالوجه. استخدمي قطرات قليلة ضمن روتينك حسب حاجة البشرة وملاءمتها للزيوت، وادمجيها بلطف دون الاقتراب من العينين أو المبالغة في الكمية.','{"nameAr":"مزيج زيت الياسمين من بيكسي","tagline":"قطرات زيت لملمس أنعم.","benefits":["مزيج زيتي للوجه","كمية قليلة للتوزيع","خطوة عناية إضافية"],"howToUse":"ربّتي قطرات قليلة على البشرة ضمن روتينك بحسب تعليمات العبوة، وتجنبي العينين.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"face-oil","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0221-df03ea5550a7.webp','https://www.pixibeauty.com/products/jasmine-oil-blend?srsltid=AfmBOopEJdLqcZ8SpSplAbK4ikuhbRUKGTaPf0BgWmuyLI9vLGOjqzBG','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0222','Julia Pop','HD Long Lasting Liquid Air Cushion','المكياج','كريم الأساس','كوشن HD السائل من جوليا بوب بالعبوة الذهبية المصوّرة. اختيار لقاعدة المكياج وتوحيد مظهر اللون بالتربيت الخفيف، مع بناء التغطية تدريجيًا؛ تأكدي من الدرجة المتاحة قبل تثبيت طلبك.','{"nameAr":"كوشن HD السائل من جوليا بوب","tagline":"كوشن لتجديد قاعدة المكياج.","benefits":["صيغة كوشن","تطبيق بالتربيت","تغطية بالتدريج"],"howToUse":"حضّري البشرة بالمرطب، ثم ادمجي طبقة رقيقة بفرشاة أو إسفنجة نظيفة. أضيفي طبقة صغيرة عند الحاجة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. عامل الحماية في المكياج لا يغني عن واقي شمس مستقل بكمية كافية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"foundation","size":"","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',6000,3990,33,'/images/catalog/TS0222-0e9f28b6c21b.webp','owner-supplied:IMG_0325.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
