INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0224','Eucerin','Anti-Pigment Dual Serum','البشرة','السيروم','سيروم أنتي بيغمنت دوال من يوسيرين للعناية بمظهر تفاوت لون البشرة. يستخدم ضمن روتين منتظم بحسب تعليمات العبوة مع واقي الشمس، دون توقع نتيجة فورية أو استخدامه على الجلد المتهيج.','{"nameAr":"سيروم أنتي بيغمنت دوال من يوسيرين","tagline":"عناية بمظهر تفاوت اللون.","benefits":["سيروم ثنائي الصيغة","عناية بمظهر اللون","يكمل روتين الحماية الشمسية"],"howToUse":"وزعي بضع قطرات على بشرة نظيفة، ثم اتبعيها بالمرطب. التزمي بكمية ووتيرة الاستخدام على العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"serum","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',20000,14990,25,'/images/catalog/TS0224-1af1bfd7e397.webp','https://www.apotekhjartat.se/varumarken/eucerin/eucerin-anti-pigment-dual-serum-30-ml','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
