INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0228','Estee Lauder','Double Wear Stay-in-Place Makeup SPF10','المكياج','كريم الأساس','كريم أساس دبل وير من إستيه لودر SPF10 بحجم 30 مل لتوحيد مظهر لون البشرة. وزعي طبقة رقيقة وادمجيها قبل إضافة المزيد حسب التغطية المطلوبة؛ رقم الدرجة يحتاج تأكيدًا قبل الطلب.','{"nameAr":"كريم أساس دبل وير من إستيه لودر","tagline":"قاعدة دبل وير لإطلالتكِ.","benefits":["كريم أساس سائل","تغطية تبنى بالتدريج","حجم 30 مل"],"howToUse":"حضّري البشرة بالمرطب، ثم ادمجي طبقة رقيقة بفرشاة أو إسفنجة نظيفة. أضيفي طبقة صغيرة عند الحاجة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. عامل الحماية في المكياج لا يغني عن واقي شمس مستقل بكمية كافية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"foundation","size":"30 ml","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false,"imageNote":"صورة توضيحية للمنتج؛ الدرجة أو تفاصيل الإصدار تُؤكّد مع المتجر."}',20000,14990,25,'/images/catalog/TS0228-7b29ba00d3ca.webp','https://www.strawberrynet.com/ja-JP/estee-lauder-double-wear-stay-in-place-makeup-spf-10-shell-1c0-30ml-1oz/248259','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
