INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0230','PanOxyl','Acne Creamy Wash Benzoyl Peroxide 4%','البشرة','الغسول والتنظيف','غسول بان أوكسيل الكريمي بتركيز بنزويل بيروكسيد 4% وحجم 170 غرامًا. منتج للحبوب له تعليمات استخدام خاصة؛ اتبعي ملصق العبوة بدقة، وابدئي بتدرج مع تجنب العينين والجلد المتشقق.','{"nameAr":"غسول بان أوكسيل الكريمي بنزويل بيروكسيد 4%","tagline":"غسول بتركيز 4% المحدد.","benefits":["بنزويل بيروكسيد 4%","غسول يُشطف","حجم 170 غرامًا"],"howToUse":"اتبعي ملصق بنزويل بيروكسيد 4% على العبوة بدقة من حيث المدة وعدد مرات الاستخدام. بللي المنطقة ودلكي بلطف ثم اشطفي جيدًا؛ ابدئي تدريجيًا إذا سمحت التعليمات.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. قد يسبب جفافًا أو يبهت الأقمشة والشعر. لا يُترك على الجلد ككريم. عند التحسس أو استمرار الحبوب استشيري الصيدلي أو الطبيب.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"cleanser","size":"170 g","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0230-19fb8e3df7a8.webp','https://www.daraz.com.bd/products/panoxyl-acne-creamy-wash-4-benzoyl-peroxide170g-i523160557.html','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0231','BIOAQUA','Honey Hand Wax','الجسم','العناية باليدين','ماسك شمع العسل لليدين من بيوأكوا للعناية بمظهر وملمس اليدين. يستخدم على اليدين بحسب خطوات ومدة العبوة ثم يزال بلطف؛ تأكدي من طريقة الإزالة المطبوعة قبل أول استخدام.','{"nameAr":"ماسك شمع العسل لليدين من بيوأكوا","tagline":"لحظة عناية ليديكِ.","benefits":["ماسك لليدين","خطوة عناية منزلية","إزالة وفق تعليمات العبوة"],"howToUse":"طبقي على اليدين النظيفتين بالطريقة والمدة المحددتين على العبوة، ثم أزيلي الماسك بلطف. لا تسخنيه أو تستخدميه قرب الحرارة إلا إذا نص الدليل على ذلك.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"body-care","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',4000,2500,37,'/images/catalog/TS0231-98345ec37bc4.webp','https://thebioaqua.com/products/bioaqua-bqy2751-6947790782751-review-milk-honey-paraffin-wax-hand-mask-hand-care-moisturizing-whitening-skin-care-exfoliating-calluses-hand-film-hand-cream','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0232','CHECK OUT','Dark Spot Corrector Whitening Cream','البشرة','المرطبات والكريمات','كريم تشيك آوت دارك سبوت كوريكتور بالعبوة الصغيرة المصوّرة للعناية بمظهر البقع وتفاوت اللون. استخدميه فقط وفق تعليمات العبوة وعلى مساحة اختبار أولًا، مع واقي الشمس في النهار.','{"nameAr":"كريم تشيك آوت للعناية بمظهر البقع","tagline":"عناية موضعية بمظهر البشرة.","benefits":["عبوة كريم صغيرة","عناية موضعية","اختبار ملاءمة قبل الاستخدام"],"howToUse":"وزعي كمية مناسبة على بشرة نظيفة بعد السيروم، ودلكي بلطف حتى الامتصاص وفق إرشادات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"moisturizer","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',4000,2500,37,'/images/catalog/TS0232-c5b0ba33374d.webp','owner-supplied:IMG_0327.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0233','CeraVe','Hydrating Mineral Sunscreen Face SPF50','البشرة','واقي الشمس','واقي هايدريتنغ المعدني للوجه من سيرافي SPF50 بحجم 75 مل. يوزع بكمية كافية كآخر خطوة للعناية الصباحية قبل المكياج، وقد يظهر أثر أبيض بحسب لون البشرة وطريقة الدمج.','{"nameAr":"واقي هايدريتنغ المعدني للوجه من سيرافي SPF50","tagline":"حماية معدنية للوجه.","benefits":["عامل SPF50","واقي معدني للوجه","عبوة 75 مل"],"howToUse":"طبقي كمية كافية ومتجانسة قبل التعرض للشمس وفق تعليمات العبوة. أعيدي التطبيق كل ساعتين وبعد السباحة أو التعرق أو التجفيف.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تجنبي شمس الظهيرة والتعرض الطويل؛ الواقي لا يوفر حماية كاملة بمفرده.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"sunscreen","size":"75 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0233-97d2f401f4c8.webp','https://mohsenistore.com/products/cerave-hydrating-mineral-sunscreen-broad-spectrum-spf50-face-75ml','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0234','Vichy','Normaderm Phytosolution Double Correction Daily Care','البشرة','المرطبات والكريمات','نورماديرم فيتوسولوشن دبل كوريكشن من فيشي للعناية اليومية بمظهر البشرة. خطوة عناية تضاف بعد التنظيف وفق تعليمات العبوة، مع التركيز على الراحة والترطيب وعدم جمع عدة مقشرات دفعة واحدة.','{"nameAr":"نورماديرم فيتوسولوشن للعناية اليومية من فيشي","tagline":"نورماديرم لروتين البشرة.","benefits":["عناية يومية بالوجه","من مجموعة نورماديرم","خطوة بعد التنظيف"],"howToUse":"وزعي كمية مناسبة على بشرة نظيفة بعد السيروم، ودلكي بلطف حتى الامتصاص وفق إرشادات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"moisturizer","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',15000,10990,26,'/images/catalog/TS0234-aa623b89c2f9.webp','https://zmcosmetics.com/en/products/vichy-normaderm-acne-prone-skin','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0235','Vichy','Normaderm Correcting Anti-Blemish Care 24H Hydration','البشرة','المرطبات والكريمات','كريم نورماديرم كوريكتنغ من فيشي بحجم 50 مل للعناية بمظهر البشرة المعرضة للشوائب. وزعي كمية مناسبة على وجه نظيف ضمن روتينك، وراقبي ملاءمة البشرة قبل زيادة وتيرة الاستخدام.','{"nameAr":"كريم نورماديرم للعناية بالبشرة من فيشي","tagline":"عناية نورماديرم اليومية.","benefits":["حجم 50 مل","عناية بمظهر الشوائب","خطوة كريمية بعد التنظيف"],"howToUse":"وزعي كمية مناسبة على بشرة نظيفة بعد السيروم، ودلكي بلطف حتى الامتصاص وفق إرشادات العبوة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"moisturizer","size":"50 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',14000,9990,28,'/images/catalog/TS0235-bca3709e5d45.webp','https://www.meagherspharmacy.ie/products/vichy-normaderm-correcting-anti-blemish-care-50ml','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0236','Eucerin','DermoPure Skin Renewal Treatment','البشرة','التقشير','ديرمو بيور سكن رينيوال من يوسيرين للعناية بملمس ومظهر البشرة. يستخدم بانتظام محسوب وفق تعليمات العبوة، مع تجنب دمجه مباشرة مع مقشرات أخرى وضرورة الحماية من الشمس صباحًا.','{"nameAr":"عناية ديرمو بيور سكن رينيوال من يوسيرين","tagline":"خطوة تجديد ضمن الروتين.","benefits":["عناية بملمس البشرة","استخدام تدريجي","من مجموعة ديرمو بيور"],"howToUse":"اتبعي تعليمات العبوة وابدئي بوتيرة متباعدة على بشرة سليمة. استخدمي مرطبًا وواقي شمس صباحًا.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تدرجي في الاستخدام وتجنبي جمعه مع مقشرات قوية في الروتين نفسه، واستخدمي واقي الشمس نهارًا.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"exfoliant","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',15000,10990,26,'/images/catalog/TS0236-0c3c691954c1.webp','https://aptekifenix.bg/euserin-dermopure-obnovyavashta-grizha-za-litse-40-ml.html','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0237','Cetaphil','Daylong Sun SPF50+ Regulating Multi-Protection Fluid','البشرة','واقي الشمس','واقي داي لونغ ريجوليتنغ ملتي بروتكشن من سيتافيل SPF50+، حجم 50 مل. فلويد لروتين الحماية اليومية، يوزع بكمية كافية على المناطق المكشوفة وتجدد طبقته خلال التعرض للشمس.','{"nameAr":"واقي الشمس داي لونغ من سيتافيل SPF50+","tagline":"فلويد حماية في عبوة عملية.","benefits":["عامل SPF50+","قوام فلويد","حجم 50 مل"],"howToUse":"طبقي كمية كافية ومتجانسة قبل التعرض للشمس وفق تعليمات العبوة. أعيدي التطبيق كل ساعتين وبعد السباحة أو التعرق أو التجفيف.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تجنبي شمس الظهيرة والتعرض الطويل؛ الواقي لا يوفر حماية كاملة بمفرده.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"sunscreen","size":"50 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',15000,10990,26,'/images/catalog/TS0237-59e5b9a24bec.webp','https://www.gosupps.com/cetaphil-sun-regulating-multi-protection-fluid-spf-50-50ml-anti-aging-sun-protection-for-the-face-donates-moisture-up-to-8-hours-absorbs-quickly-and-is-ultra-light-not-comedogenic.html','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0238','La Roche-Posay','Anthelios Invisible Fluid SPF50+','البشرة','واقي الشمس','فلويد أنثيليوس غير المرئي من لاروش بوزيه SPF50+ بحجم 50 مل. يُرج حسب تعليمات العبوة قبل توزيع طبقة كافية ومتجانسة، ويعاد تطبيقه أثناء الخروج وبعد التعرق أو السباحة.','{"nameAr":"واقي أنثيليوس الفلويد غير المرئي من لاروش بوزيه SPF50+","tagline":"حماية أنثيليوس اليومية.","benefits":["عامل SPF50+","فلويد يُرج قبل الاستخدام","حجم 50 مل"],"howToUse":"طبقي كمية كافية ومتجانسة قبل التعرض للشمس وفق تعليمات العبوة. أعيدي التطبيق كل ساعتين وبعد السباحة أو التعرق أو التجفيف.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تجنبي شمس الظهيرة والتعرض الطويل؛ الواقي لا يوفر حماية كاملة بمفرده.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"sunscreen","size":"50 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',16000,11990,25,'/images/catalog/TS0238-67ff8d50a73c.webp','https://www.regentsparkpharmacy.com.au/products/la-roche-posay-anthelios-invisible-fluid-face-spf50-50ml','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0239','La Roche-Posay','Hydreane BB Cream SPF20','المكياج','كريمات BB وCC','كريم هيدريان BB من لاروش بوزيه SPF20 بحجم 40 مل يجمع لمسة لونية مع خطوة عناية للوجه. يدمج بالتدريج لإطلالة يومية خفيفة، مع تأكيد الدرجة المتاحة وعدم الاكتفاء به بدل واقي الشمس.','{"nameAr":"كريم هيدريان BB من لاروش بوزيه SPF20","tagline":"لون خفيف في خطوة BB.","benefits":["كريم BB ملون","توحيد مظهر اللون","عبوة 40 مل"],"howToUse":"ادمجي طبقة رقيقة على بشرة مرطبة وقارني اللون في إضاءة طبيعية. استخدمي واقي شمس مستقلًا بكمية كافية.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. عامل الحماية في المكياج لا يغني عن واقي شمس مستقل بكمية كافية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"bb-cc","size":"40 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',14000,9990,28,'/images/catalog/TS0239-4128fc99153f.webp','https://www.notino.fr/la-roche-posay/hydreane-bb-creme-teintee-hydratante-spf-20/','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0240','La Roche-Posay','Hydraphase HA BB Cream SPF15 Light','المكياج','كريمات BB وCC','كريم هيدرافاز HA BB من لاروش بوزيه بدرجة Light وعامل SPF15، حجم 40 مل. اختيار لقاعدة لونية خفيفة يوزع على البشرة المرطبة، مع التأكد من ملاءمة الدرجة واستخدام حماية شمس مستقلة.','{"nameAr":"كريم هيدرافاز HA BB من لاروش بوزيه — فاتح","tagline":"BB بلمسة فاتحة.","benefits":["درجة Light الفاتحة","كريم BB","حجم 40 مل"],"howToUse":"ادمجي طبقة رقيقة على بشرة مرطبة وقارني اللون في إضاءة طبيعية. استخدمي واقي شمس مستقلًا بكمية كافية.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. عامل الحماية في المكياج لا يغني عن واقي شمس مستقل بكمية كافية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"bb-cc","size":"40 ml","shade":"Light — فاتح","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',15000,10990,26,'/images/catalog/TS0240-041a533aafaa.webp','https://www.zurrose-shop.ch/de/hydraphase-ha-bb-creme-light/dp/28J0NTR9','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0241','La Roche-Posay','Cicaplast B5 Care — Photographed Pack 40 ml','البشرة','المرطبات والكريمات','عناية سيكابلاست B5 من لاروش بوزيه بالعبوة المصوّرة 40 مل. تظهر على العبوة تسميات Brume وBaume؛ لذلك تُؤكّد صيغة العبوة وطريقة توزيعها مع المتجر، ولا يُفترض أنها بخاخ من الصورة وحدها.','{"nameAr":"عناية سيكابلاست B5 من لاروش بوزيه — العبوة المصوّرة","tagline":"عناية سيكابلاست B5.","benefits":["مجموعة سيكابلاست B5","العبوة المصوّرة 40 مل","تأكيد الصيغة قبل الاستخدام"],"howToUse":"أكدي صيغة المنتج مع المتجر أولًا، ثم اتبعي طريقة التوزيع المطبوعة على العبوة نفسها. لا ترشي المنتج قرب الوجه بناءً على اسم Brume فقط.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"moisturizer","size":"40 ml","shade":"","variantNote":"صيغة العبوة تحتاج تأكيدًا مع المتجر قبل الطلب؛ الوصف لا يفترض أنها بخاخ.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',14000,9990,28,'/images/catalog/TS0241-08dbd4547484.webp','owner-supplied:IMG_0328.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0242','Mielle','Rosemary Mint Scalp Hair Strengthening Oil','الشعر','الزيوت والسيروم','زيت روزماري منت من ميلي بحجم 59 مل للعناية بالشعر وفروة الرأس بحسب تعليمات العبوة. وزعي كمية قليلة على المناطق المناسبة ودلكي بلطف، دون وعد بتغيير نمو الشعر أو علاج التساقط.','{"nameAr":"زيت روزماري منت للشعر من ميلي","tagline":"عناية روزماري ومنت للشعر.","benefits":["زيت للشعر","روزماري ومنت","حجم 59 مل"],"howToUse":"وزعي كمية قليلة على الأطوال أو المناطق المسموح بها على العبوة. لا تفرطي بالكمية وراقبي ملاءمة فروة الرأس.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. نتيجة تجميلية للعناية والمظهر، وليس علاجًا مثبتًا لتساقط الشعر.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"hair-oil","size":"59 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',10000,7500,25,'/images/catalog/TS0242-bac676b2bc1d.webp','https://www.justmylook.com/products/mielle-rosemary-mint-scalp-hair-strengthening-oil-59ml','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0243','Mielle','Rosemary Mint Strengthening Shampoo','الشعر','الشامبو','شامبو روزماري منت من ميلي بحجم 355 مل لتنظيف الشعر ضمن روتين الغسل. يدلك على شعر مبلل ثم يشطف جيدًا، ويمكن متابعة الروتين بالبلسم المناسب لسهولة ترتيب الخصلات.','{"nameAr":"شامبو روزماري منت من ميلي","tagline":"بداية روتين روزماري منت.","benefits":["شامبو للشعر","يُشطف بعد التدليك","عبوة 355 مل"],"howToUse":"دلكي كمية مناسبة على شعر مبلل وفروة الرأس ثم اشطفي جيدًا. كرري فقط عند الحاجة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"shampoo","size":"355 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0243-6b618477fe69.webp','https://www.walmart.ca/en/ip/Mielle-Rosemary-Mint-Strengthening-Shampoo-Clarifying-Shampoo-that-Gently-Cleanses-Helps-Strengthen-Hair/4SM9ZX6777C9','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
