INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0246','Bourjois','Healthy Mix Pressed Powder 52','المكياج','البودرة','بودرة هيلثي ميكس المضغوطة من بورجوا بالعبوة الحمراء ودرجة 52 الظاهرة في الصورة. تطبق بطبقات خفيفة لتثبيت مظهر المكياج وتخفيف اللمعان، مع التركيز على المناطق التي تحتاج لمسة بودرة.','{"nameAr":"بودرة هيلثي ميكس من بورجوا — درجة 52","tagline":"بودرة هيلثي ميكس بدرجة 52.","benefits":["درجة 52","بودرة مضغوطة","العبوة الحمراء المصوّرة"],"howToUse":"خذي كمية قليلة بفرشاة أو إسفنجة نظيفة، وانفضي الزائد ثم طبقي طبقة خفيفة على المناطق المطلوبة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"powder","size":"","shade":"52","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',10000,7000,30,'/images/catalog/TS0246-e469cf71ca5d.webp','owner-supplied:IMG_0330.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
