INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0248','The Ordinary','Serum Foundation Light Coverage','المكياج','كريم الأساس','سيروم فاوندَيشن من ذا أورديناري بحجم 30 مل وتغطية خفيفة بحسب العبوة. يوزع على الوجه بطبقات قليلة لإطلالة أقرب للطبيعية، مع ضرورة تأكيد رقم الدرجة لأن العبوة المصوّرة لا تظهره بوضوح.','{"nameAr":"كريم أساس سيروم فاوندَيشن من ذا أورديناري","tagline":"تغطية خفيفة بقوام سيروم.","benefits":["تغطية خفيفة","قوام سيروم","عبوة 30 مل"],"howToUse":"حضّري البشرة بالمرطب، ثم ادمجي طبقة رقيقة بفرشاة أو إسفنجة نظيفة. أضيفي طبقة صغيرة عند الحاجة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. عامل الحماية في المكياج لا يغني عن واقي شمس مستقل بكمية كافية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"foundation","size":"30 ml","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false,"imageNote":"صورة توضيحية للمنتج؛ الدرجة أو تفاصيل الإصدار تُؤكّد مع المتجر."}',12000,8990,25,'/images/catalog/TS0248-320c28419732.webp','https://www.farmasiet.no/catalog/ansiktspleie/kosmetikk/the-ordinary-serum-foundation8%2C5009777','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0249','حسب العبوة','Argan Oil Keratin Gold Hair Oil','الشعر','الزيوت والسيروم','زيت الأرغان بالكيراتين غولد للشعر بالعبوة السوداء ذات المضخة الذهبية المصوّرة. توزع كمية قليلة على الأطوال والأطراف وفق تعليمات العبوة لإضافة خطوة عناية ولمسة ترتيب إلى التصفيف.','{"nameAr":"زيت الأرغان بالكيراتين غولد للشعر","tagline":"لمسة زيت لأطراف الشعر.","benefits":["عبوة بمضخة","للأطوال والأطراف","كمية قليلة للتحكم"],"howToUse":"وزعي كمية قليلة على الأطوال أو المناطق المسموح بها على العبوة. لا تفرطي بالكمية وراقبي ملاءمة فروة الرأس.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. نتيجة تجميلية للعناية والمظهر، وليس علاجًا مثبتًا لتساقط الشعر.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"hair-oil","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',5000,2500,50,'/images/catalog/TS0249-bfe7728bee7d.webp','owner-supplied:IMG_0330.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
