INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0257','Miss Lara','Sky High Mascara Green Tube','المكياج','المسكارا','ماسكارا سكاي هاي من ميس لارا بالأنبوب الأخضر والعبوة المصوّرة 16 مل. خيار لإبراز مظهر الرموش بتمريرات خفيفة؛ الأخضر يصف لون العبوة فقط، أما لون التركيبة فيُؤكّد مع المتجر.','{"nameAr":"ماسكارا سكاي هاي ميس لارا — العبوة الخضراء","tagline":"سكاي هاي بعبوة خضراء.","benefits":["من ميس لارا","عبوة خضراء 16 مل","تعريف مظهر الرموش"],"howToUse":"مرري الفرشاة من جذور الرموش إلى الأطراف بحركات خفيفة. زيدي طبقة بحسب الإطلالة وأزيلي المكياج بلطف مساءً.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"mascara","size":"16 ml","shade":"","variantNote":"لون الأخضر/الأزرق يصف العبوة فقط؛ أكدي لون تركيبة الماسكارا مع المتجر قبل الطلب.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',4000,2000,50,'/images/catalog/TS0257-97b7c2859bee.webp','owner-supplied:IMG_0331.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
