INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0259','Romantic Matte','Wonder Stick Highlight Contour','المكياج','الكونتور','ستيك وندر من رومانتيك مات للهايلايتر والكونتور بحسب العبوة ثنائية الطرف المصوّرة. استخدمي كمية صغيرة في مناطق التحديد والإضاءة وادمجيها جيدًا، مع تأكيد الدرجات المتاحة مع المتجر.','{"nameAr":"ستيك وندر للهايلايتر والكونتور من رومانتيك مات","tagline":"تحديد وإضاءة بخطوتين.","benefits":["ستيك ثنائي الطرف","للتحديد والإضاءة","دمج بكمية قليلة"],"howToUse":"حددي المناطق المطلوبة بكمية قليلة ثم ادمجي الحواف جيدًا بفرشاة أو إسفنجة نظيفة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"contour","size":"","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',5000,3500,30,'/images/catalog/TS0259-fb5dc977112a.webp','owner-supplied:IMG_0331.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0260','Beauty Tools','Crystal Hair Removal Exfoliator BD612','الأدوات','إزالة الشعر','أداة إزالة الشعر الكريستالية BD612 باللون الفيروزي والشكل البيضاوي المصوّر على العبوة. استخدميها فقط على مناطق الجسم المسموح بها وبضغط خفيف وفق دليلها، مع اختبار جزء صغير أولًا.','{"nameAr":"أداة إزالة الشعر الكريستالية BD612","tagline":"أداة كريستالية للعناية المنزلية.","benefits":["الموديل BD612","تصميم بيضاوي","أداة قابلة لإعادة الاستخدام"],"howToUse":"اتبعي دليل الأداة واختبري مساحة صغيرة من الجسم أولًا. استخدمي حركة وضغطًا خفيفين فقط على المناطق المسموح بها، وتوقفي عند الاحمرار.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. لا يستخدم على الجروح أو الجلد الملتهب؛ استشيري مختصًا قبل استخدامه عند السكري أو ضعف الإحساس أو الدورة الدموية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"hair-removal","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',4000,2500,37,'/images/catalog/TS0260-a5411c8847d7.webp','owner-supplied:IMG_0331.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0261','Benefit','Benetint Rose Tinted Lip Cheek Stain','المكياج','الشفاه','بنيتنت من بنفت صبغة سائلة للشفاه والخدود بحجم 12.5 مل. توزع نقاط قليلة وتدمج بسرعة للحصول على لمسة لون، ثم تزاد بالتدريج حسب الإطلالة؛ ضعيها على بشرة سليمة وشفاه مرتاحة.','{"nameAr":"بنيتنت صبغة الشفاه والخدود من بنفت","tagline":"لون وردي للشفاه والخدود.","benefits":["للشفاه والخدود","لون Rose بحسب العبوة","حجم 12.5 مل"],"howToUse":"ضعي نقاطًا قليلة على الخدود أو الشفاه السليمة وادمجي مباشرة. زيدي اللون تدريجيًا وأغلقي العبوة بعد الاستخدام.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"lips","size":"12.5 ml","shade":"Rose","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0261-4bece12dae48.webp','https://www.ebay.com.au/shop/benetint?_nkw=benetint','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0262','Emelie','Loose Powder','المكياج','البودرة','بودرة إيميلي السائبة بالعلبة البيج المصوّرة لخطوة تثبيت المكياج. خذي مقدارًا قليلًا بفرشاة أو إسفنجة وانفضي الزائد قبل التطبيق لتوزيع خفيف؛ الدرجة النهائية تُؤكّد مع المتجر.','{"nameAr":"بودرة إيميلي السائبة","tagline":"بودرة سائبة للمسة ختامية.","benefits":["بودرة سائبة","خطوة لتثبيت المكياج","توزيع خفيف للوجه"],"howToUse":"خذي كمية قليلة بفرشاة أو إسفنجة نظيفة، وانفضي الزائد ثم طبقي طبقة خفيفة على المناطق المطلوبة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"powder","size":"","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',5000,3500,30,'/images/catalog/TS0262-d59f17dd6dff.webp','owner-supplied:IMG_0331.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0263','The Ordinary','Mineral UV Filters SPF30 with Antioxidants','البشرة','واقي الشمس','واقي الشمس مينيرال يو في فلترز SPF30 مع مضادات الأكسدة من ذا أورديناري بحجم 50 مل. النسخة المصوّرة تحمل SPF30؛ توزع بكمية كافية وتجدد خلال اليوم، وقد تترك أثرًا أبيض بحسب البشرة.','{"nameAr":"واقي الشمس المعدني SPF30 من ذا أورديناري","tagline":"واقي معدني SPF30 المحدد.","benefits":["واقي معدني SPF30","النسخة المصوّرة 50 مل","خطوة حماية صباحية"],"howToUse":"طبقي كمية كافية ومتجانسة قبل التعرض للشمس وفق تعليمات العبوة. أعيدي التطبيق كل ساعتين وبعد السباحة أو التعرق أو التجفيف.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تجنبي شمس الظهيرة والتعرض الطويل؛ الواقي لا يوفر حماية كاملة بمفرده.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"sunscreen","size":"50 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0263-e52c41cef92e.webp','https://review.soco.id/product/sunscreen/24092-mineral-uv-filters-with-antioxidants-spf-30','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0264','حسب العبوة','Makeup Brow Kit 6 Colors','المكياج','الحواجب','باليت حواجب ميك أب برو كيت 6 ألوان بالعبوة السوداء والذهبية المصوّرة. اختاري الدرجة الأنسب لحاجبيك واستخدمي فرشاة رفيعة لملء الفراغات بخفة؛ توزيع الألوان الداخلي يُؤكّد مع المتجر.','{"nameAr":"باليت الحواجب 6 ألوان","tagline":"درجات لترتيب مظهر الحواجب.","benefits":["6 ألوان بحسب العبوة","لتحديد مظهر الحاجبين","عبوة تجمع الدرجات"],"howToUse":"اختاري الطرف أو الدرجة المناسبة وارسمي خطوطًا خفيفة باتجاه الشعر، ثم ادمجي للمظهر المطلوب.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"brows","size":"","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',6000,3000,50,'/images/catalog/TS0264-8034ac05e88e.webp','owner-supplied:IMG_0332.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0265','Huda Beauty','Naughty Nude Eyeshadow Palette Burgundy','المكياج','باليت العيون','باليت ظلال نوتي نود بالعبوة العنابية المصوّرة لإطلالات مكياج العيون. اختاري درجات متناسقة وادمجيها تدريجيًا على الجفن، مع تأكيد نسخة وألوان الباليت المتاحة قبل تثبيت الطلب.','{"nameAr":"باليت ظلال نوتي نود — العبوة العنابية","tagline":"نوتي نود للعينين.","benefits":["باليت لظلال العين","العبوة العنابية","تنسيق ودمج الألوان"],"howToUse":"وزعي الظلال على الجفن بفرشاة نظيفة وادمجي بالتدريج. تجنبي دخول المنتج إلى العين.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"eyeshadow","size":"","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false,"imageNote":"صورة توضيحية للمنتج؛ الدرجة أو تفاصيل الإصدار تُؤكّد مع المتجر."}',16000,11990,25,'/images/catalog/TS0265-a378ff64209c.webp','https://www.marieclaire.co.uk/beauty/huda-beauty-black-friday-713495','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
