INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0267','COVER FX','The Perfect Light Highlighting Palette','المكياج','الهايلايتر','باليت ذا بيرفكت لايت للهايلايتر من كفر إف إكس بالعبوة الفاتحة المصوّرة. يستخدم لإضافة الإضاءة إلى نقاط الوجه المطلوبة؛ شكل العبوة واضح، بينما الدرجات الداخلية تُؤكّد مع المتجر.','{"nameAr":"باليت ذا بيرفكت لايت للهايلايتر من كفر إف إكس","tagline":"إضاءة ذا بيرفكت لايت.","benefits":["باليت هايلايتر","لنقاط الإضاءة","عبوة The Perfect Light"],"howToUse":"ضعي كمية صغيرة على نقاط الإضاءة مثل أعلى الخدين وادمجي بلطف بعيدًا عن العينين.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"highlighter","size":"","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',12000,8990,25,'/images/catalog/TS0267-a0073d3613bd.webp','owner-supplied:IMG_0333.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
