INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0269','Benefit','BADgal BANG Volumizing Mascara','المكياج','المسكارا','ماسكارا باد غال بانغ من بنفت لإبراز مظهر كثافة الرموش وتعريفها. وزعي طبقة من الجذور للأطراف وأضيفي المزيد حسب الإطلالة؛ أزيليها بلطف بمزيل مناسب في نهاية اليوم.','{"nameAr":"ماسكارا باد غال بانغ من بنفت","tagline":"باد غال بانغ لرموش بارزة.","benefits":["إبراز مظهر الكثافة","فرشاة للرموش","تطبيق طبقة بعد أخرى"],"howToUse":"مرري الفرشاة من جذور الرموش إلى الأطراف بحركات خفيفة. زيدي طبقة بحسب الإطلالة وأزيلي المكياج بلطف مساءً.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"mascara","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0269-8ffac00a4c8c.webp','https://www.ace.co.uk/benefit-badgal-bang-volumising-mascara-771315','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0270','The Ordinary','Saccharomyces Ferment 30% Milky Toner','البشرة','التونر','تونر ساكارومايسس فيرمنت 30% الميلكي من ذا أورديناري بحجم 100 مل. خطوة سائلة للعناية بملمس البشرة بعد التنظيف، تستخدم وفق إرشادات المنتج مع التدرج ومتابعتها بالمرطب والحماية الشمسية.','{"nameAr":"تونر ساكارومايسس فيرمنت 30% الميلكي من ذا أورديناري","tagline":"خطوة تونر بقوام ميلكي.","benefits":["تونر ميلكي","ساكارومايسس فيرمنت 30%","حجم 100 مل"],"howToUse":"وزعي كمية قليلة بعد تنظيف البشرة وفق تعليمات العبوة، ثم تابعي بالمرطب. ابدئي بوتيرة متباعدة إذا كانت التركيبة مقشرة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. تدرجي في الاستخدام وتجنبي جمعه مع مقشرات قوية في الروتين نفسه، واستخدمي واقي الشمس نهارًا.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"toner","size":"100 ml","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',14000,9990,28,'/images/catalog/TS0270-89a659fd21e3.webp','https://www.sephora.co.th/products/the-ordinary-saccharomyces-ferment-30-percent-milky-toner','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
