INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0272','Maybelline','Fit Me Luminous Smooth Foundation 120 Classic Ivory','المكياج','كريم الأساس','كريم أساس فيت مي لومينوس سموث من ميبيلين بدرجة 120 Classic Ivory الظاهرة على العبوة. يدمج على الوجه لتوحيد مظهر اللون ولمسة مضيئة، مع مقارنة الدرجة ببشرتك في إضاءة طبيعية.','{"nameAr":"كريم أساس فيت مي لومينوس سموث من ميبيلين — 120","tagline":"فيت مي بدرجة 120.","benefits":["درجة 120 Classic Ivory","نسخة Luminous Smooth","قاعدة سائلة للوجه"],"howToUse":"حضّري البشرة بالمرطب، ثم ادمجي طبقة رقيقة بفرشاة أو إسفنجة نظيفة. أضيفي طبقة صغيرة عند الحاجة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. عامل الحماية في المكياج لا يغني عن واقي شمس مستقل بكمية كافية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"foundation","size":"","shade":"120 Classic Ivory","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',10000,6990,30,'/images/catalog/TS0272-4a6eff177f8c.webp','https://rozetka.pl/396193635/p396193635/','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0273','Yo-Siken','Air Stocking Leg Makeup','الجسم','مكياج الجسم','إير ستوكينغ من يو سيكن بالعبوة البيج ذات النافذة المصوّرة لتوحيد مظهر لون الساقين تجميليًا. اتبعي تعليمات التطبيق على العبوة واتركي اللون يستقر قبل الملابس، مع تأكيد الدرجة المتاحة.','{"nameAr":"إير ستوكينغ لتوحيد مظهر لون الساقين","tagline":"لمسة لونية لمظهر الساقين.","benefits":["مكياج للجسم","لمظهر لون أكثر تجانسًا","العبوة البيج المصوّرة"],"howToUse":"اتبعي تعليمات العبوة لتوزيع طبقة رقيقة على الساقين السليمتين. اتركي اللون يستقر قبل ارتداء الملابس واختبري احتمال انتقاله للقماش.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"body-care","size":"","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',6000,3990,33,'/images/catalog/TS0273-a1a77607985f.webp','owner-supplied:IMG_0335.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
