INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0275','L''Oreal Paris','Infallible 24H Fresh Wear Foundation in a Powder 200 Ivory','المكياج','البودرة','بودرة كريم أساس إنفاليبل فريش وير من لوريال بدرجة 200 Ivory وحجم 9 غرامات. تستخدم منفردة أو فوق القاعدة بطبقات خفيفة لتوحيد مظهر اللون؛ النسخة المصوّرة 200 وليست درجة 20.','{"nameAr":"بودرة إنفاليبل فريش وير من لوريال — 200 آيفوري","tagline":"فريش وير بدرجة 200 آيفوري.","benefits":["درجة 200 Ivory","بودرة كريم أساس","حجم 9 غرامات"],"howToUse":"خذي كمية قليلة بفرشاة أو إسفنجة نظيفة، وانفضي الزائد ثم طبقي طبقة خفيفة على المناطق المطلوبة.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"powder","size":"9 g","shade":"200 Ivory","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',12000,8990,25,'/images/catalog/TS0275-0c2559779012.webp','owner-supplied:IMG_0335.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0276','BAOL','Pedicure Foot File','الأدوات','العناية بالقدمين','مبرد القدمين من باول بالعبوة الصفراء المصوّرة للعناية بالجلد الخشن في المناطق المناسبة. يستخدم برفق حسب تعليماته دون إزالة مفرطة للجلد، وينظف ويجفف بعد الاستخدام ليبقى جاهزًا لروتينك.','{"nameAr":"مبرد القدمين من باول","tagline":"خطوة مرتبة للعناية بالقدمين.","benefits":["أداة للعناية بالقدمين","مقبض لسهولة التحكم","قابل للتنظيف بعد الاستخدام"],"howToUse":"استخدمي المبرد بلطف على مناطق الجلد الخشن المناسبة وفق دليله، دون إفراط. نظفيه وجففيه بعد الاستخدام.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية. لا يستخدم على الجروح أو الجلد الملتهب؛ استشيري مختصًا قبل استخدامه عند السكري أو ضعف الإحساس أو الدورة الدموية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"foot-tools","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":true,"imageNote":"صورة محسّنة بالذكاء الاصطناعي اعتمادًا على العبوة المصوّرة؛ تُراجع التفاصيل على العبوة الفعلية."}',3000,1500,50,'/images/catalog/TS0276-df4920ac97d6.webp','owner-supplied:IMG_0336.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0277','Feather','Flamingos Facial Razors 3 Pack','الأدوات','إزالة الشعر','شفرات فيذر فلامينغوس للوجه، مجموعة من 3 قطع كما في العبوة المصوّرة. استخدمي شفرة نظيفة بحركات قصيرة وخفيفة وفق التعليمات، وتجنبي البشرة المتهيجة أو مشاركة الشفرة مع الآخرين.','{"nameAr":"شفرات فلامينغوس للوجه — 3 قطع","tagline":"ترتيب بسيط لشعر الوجه.","benefits":["مجموعة 3 قطع","للترتيب بحركات خفيفة","مقبض عملي للاستخدام"],"howToUse":"استخدمي شفرة نظيفة بحركات قصيرة وخفيفة حسب تعليمات العبوة، بعيدًا عن الجلد المتهيج والحبوب. لا تشاركي الشفرة وتخلّصي منها إذا تلفت.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"hair-removal","size":"3 pieces","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',4000,2500,37,'/images/catalog/TS0277-3b4fda223ed2.webp','https://ananinja.com/sa/ar/product/feather-flamingo-for-women-to-remove-facial-hair-consisting-of-3-blades-13991175','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
