INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0284','L''Oreal Paris','Volume Million Lashes Panorama Gold Packaging','المكياج','المسكارا','ماسكارا بانوراما من لوريال بالأنبوب الذهبي المصوّر لإبراز مظهر كثافة الرموش وتعريفها. طبقيها بتمريرات خفيفة من الجذور للأطراف؛ هذه النسخة منفصلة عن إصدار All Night Black الأسود.','{"nameAr":"ماسكارا بانوراما من لوريال — العبوة الذهبية","tagline":"بانوراما بالعبوة الذهبية.","benefits":["عبوة بانوراما الذهبية","إبراز مظهر الكثافة","تطبيق تدريجي بالفرشاة"],"howToUse":"مرري الفرشاة من جذور الرموش إلى الأطراف بحركات خفيفة. زيدي طبقة بحسب الإطلالة وأزيلي المكياج بلطف مساءً.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"mascara","size":"","shade":"","variantNote":"","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false}',12000,8990,25,'/images/catalog/TS0284-d7c7a4eba834.webp','https://leomarka.com/products/panorama-volume-million-lashes-mascara-by-loreal','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TS0285','Tarte','Shape Tape Contour Concealer','المكياج','الكونسيلر','كونسيلر شيب تيب كونتور من تارت لتغطية موضعية ودمج لمسات المكياج. استخدمي نقاطًا قليلة وادمجيها بلطف بإسفنجة أو فرشاة، مع تأكيد رقم الدرجة المتاحة قبل الطلب لأن الصورة لا تحدده.','{"nameAr":"كونسيلر شيب تيب من تارت","tagline":"شيب تيب للمسات التغطية.","benefits":["كونسيلر سائل","تغطية موضعية","دمج بكمية قليلة"],"howToUse":"ضعي نقاطًا قليلة على المناطق المطلوبة وادمجي بالتربيت بفرشاة أو إسفنجة نظيفة، ثم ثبتي بخفة إذا رغبتِ.","notes":"للاستخدام الخارجي. اختبري الملاءمة على مساحة صغيرة، وتوقفي عند التهيج. اتبعي تعليمات العبوة وتحققي من الصلاحية.","imageType":"photo","collection":"beauty","featuredOrder":100,"productType":"concealer","size":"","shade":"","variantNote":"الدرجة اللونية غير محددة في الصور المرسلة. أكدي اللون المتاح مع المتجر عبر واتساب قبل تثبيت الطلب؛ الصورة لا تمثل وعدًا بدرجة بعينها.","introductoryOffer":true,"intakeBatch":"2026-10-27","imageEditedWithAI":false,"imageNote":"صورة توضيحية للمنتج؛ الدرجة أو تفاصيل الإصدار تُؤكّد مع المتجر."}',12000,8990,25,'/images/catalog/TS0285-7040503e9060.webp','owner-supplied:IMG_0342.jpeg','Owner intake 2026-10-27',24,1,1) ON CONFLICT(id) DO NOTHING;
